    const groups = ['High', 'Upper-Middle', 'Lower-Middle', 'Low'];

    function css(name) {
      return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
    }

    const groupColor = {
      'High': css('--c-high'),
      'Upper-Middle': css('--c-upper'),
      'Lower-Middle': css('--c-lower'),
      'Low': css('--c-low'),
    };

    const groupFill = {
      'High': css('--hi'),
      'Upper-Middle': css('--up'),
      'Lower-Middle': css('--lo'),
      'Low': css('--lw'),
    };

    function clamp01(x) { return Math.max(0, Math.min(1, x)); }

    // Compute min/max per dimension
    const minMax = {};
    for (const d of dims) {
      let mn = Infinity, mx = -Infinity;
      for (const r of DATA) {
        const v = Number(r[d.key]);
        if (!Number.isFinite(v)) continue;
        if (v < mn) mn = v;
        if (v > mx) mx = v;
      }
      minMax[d.key] = { min: mn, max: mx };
    }

    function normalize(key, v) {
      const { min, max } = minMax[key];
      if (max === min) return 0.5;
      return clamp01((v - min) / (max - min));
    }

    // Quantile helper (for median)
    function quantile(sorted, q) {
      const pos = (sorted.length - 1) * q;
      const base = Math.floor(pos);
      const rest = pos - base;
      if (sorted[base + 1] !== undefined) {
        return sorted[base] + rest * (sorted[base + 1] - sorted[base]);
      }
      return sorted[base];
    }

    // Compute group medians per dimension in normalized space
    const medians = {};
    for (const g of groups) {
      medians[g] = {};
