        ctx.stroke();

        if (ln.outlier) {
          // small rings at endpoints to emphasize profile without clutter
          ctx.globalAlpha = 0.85;
          ctx.fillStyle = css('--surface');
          ctx.strokeStyle = col;
          ctx.lineWidth = 2 * ratio;
          for (const idx of [0, ln.pts.length-1]) {
            const p = ln.pts[idx];
            ctx.beginPath();
            ctx.arc(p.x, p.y, 3.6*ratio, 0, Math.PI*2);
            ctx.fill();
            ctx.stroke();
          }
        }
      }
      ctx.restore();

      // Group median polylines (bold)
      ctx.save();
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';
      for (const g of groups) {
        const pts = dims.map((d, i) => {
          const v = medians[g][d.key];
          const y = padT + (1 - v) * plotH;
          return { x: xs[i], y };
        });
        ctx.strokeStyle = groupColor[g];
        ctx.globalAlpha = 0.92;
        ctx.lineWidth = 3.1 * ratio;
        ctx.beginPath();
        ctx.moveTo(pts[0].x, pts[0].y);
        for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
        ctx.stroke();

        // median label on left
        ctx.globalAlpha = 0.95;
        ctx.fillStyle = groupColor[g];
        ctx.font = `${10*ratio}px ${css('--font-mono')}`;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText(`${g} median`, padL + 8*ratio, pts[0].y);
      }
      ctx.restore();

      // Annotate a few notable outliers (right side labels)
      // Choose top 6 by outlier score (already computed in DATA as __outScore)
      const outRows = DATA.filter(r => outliers.has(r.country))
        .slice()
        .sort((a,b)=> (b.__outScore||0) - (a.__outScore||0))
        .slice(0, 6);

      ctx.save();
      ctx.font = `${11*ratio}px ${css('--font-mono')}`;
      ctx.textAlign = 'left';
      ctx.textBaseline = 'middle';
      const xLabel = w - padR - 150*ratio;
      let yCursor = padT + 16*ratio;

      for (const r of outRows) {
        const g = r.income_group;
        const col = groupColor[g];
        // y position at CO2 axis for callout anchor
        const iCO2 = dims.findIndex(d => d.key === 'co2_emissions_per_capita_tons');
        const v = normalize('co2_emissions_per_capita_tons', Number(r.co2_emissions_per_capita_tons));
        const yAnchor = padT + (1 - v) * plotH;

        // label box position
        const y = Math.max(padT + 14*ratio, Math.min(padT + plotH - 14*ratio, yAnchor));

        // connector
        ctx.strokeStyle = col;
        ctx.globalAlpha = 0.55;
        ctx.lineWidth = 1.2*ratio;
        ctx.beginPath();
        ctx.moveTo(xs[iCO2], yAnchor);
        ctx.lineTo(xLabel - 10*ratio, y);
        ctx.stroke();

        // label pill
        const text = r.country;
        const padX = 8*ratio;
        const padY = 5*ratio;
        const tw = ctx.measureText(text).width;
        const bw = tw + padX*2;
        const bh = 22*ratio;
        const bx = xLabel;
        const by = y - bh/2;

        ctx.fillStyle = css('--surface');
        ctx.globalAlpha = 0.92;
        ctx.strokeStyle = col;
        ctx.lineWidth = 1.4*ratio;
        roundRect(ctx, bx, by, bw, bh, 999*ratio);
        ctx.fill();
        ctx.stroke();

        ctx.fillStyle = col;
        ctx.globalAlpha = 0.95;
        ctx.fillText(text, bx + padX, y);

        yCursor += 22*ratio;
      }
      ctx.restore();

      // Left-side y-scale label
      ctx.save();
      ctx.fillStyle = css('--text-dim');
      ctx.font = `${11*ratio}px ${css('--font-mono')}`;
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillText('Scaled value (min → max)', padL, 6*ratio);
      ctx.restore();

      // y ticks labels 0/0.5/1
      ctx.save();
      ctx.fillStyle = css('--text-dim');
      ctx.font = `${10*ratio}px ${css('--font-mono')}`;
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      for (const t of [1, 0.75, 0.5, 0.25, 0]) {
        const y = padT + (1 - t) * plotH;
        ctx.fillText(String(t), padL - 10*ratio, y);
      }
      ctx.restore();
    }

    function roundRect(ctx, x, y, w, h, r) {
      const rr = Math.min(r, w/2, h/2);
      ctx.beginPath();
      ctx.moveTo(x + rr, y);
      ctx.arcTo(x + w, y, x + w, y + h, rr);
      ctx.arcTo(x + w, y + h, x, y + h, rr);
      ctx.arcTo(x, y + h, x, y, rr);
      ctx.arcTo(x, y, x + w, y, rr);
      ctx.closePath();
    }

    window.addEventListener('resize', () => draw(), { passive: true });
    draw();
  </script>
</body>
